import hashlib

def page(account, boundary, existing, maximum):
    if boundary not in existing.get(account, set()) or boundary > maximum:
        raise ValueError('invalid boundary')
    return {'account': account, 'after': boundary}

def quote(account, chat, token, record, now):
    if (record['account'], record['chat']) != (account, chat):
        raise ValueError('ownership')
    if hashlib.sha256(token.encode()).hexdigest() != record['digest'] or now > record['expires']:
        raise ValueError('token')
    return record['price']

